#!/bin/sh
# Validate .desktop file generated by "org_protocol_debug.py -d"
#
# Run desktop-file-validate(1) on the script output.
# The wrapper is necessary since the linter  does not accept standard input.

die()
{
	exitcode="$1"
	shift
	printf '%s: %s\n' "$0" "$*" 1>&2
	exit "$exitcode"
}

cleanup()
{
	[ -z "${tmpfile:+tmpfile created}" ] ||
		rm "$tmpfile"
	[ -z "${tmpdir:+tmpdir created}" ] ||
		rmdir "$tmpdir"
}

[ -z "${1+set}" ] ||
	die 2 "arguments are not supported: $*"

validate="$(command -v desktop-file-validate)" ||
	die 0 "desktop-file-validate tool not found. SKIP"
script="$(dirname "$0")/org_protocol_debug.py"
[ -x "$script" ] ||
	die 1 "$script: not executable. FAIL"

# Busybox does not support template suffix
# while desktop-file-validate requires it
#
#     busybox mktemp -t org_protocol_debug_XXXXXXXXXX.desktop
#     mktemp: (null): Invalid argument
tmpdir="$(mktemp -d -t test_desktopXXXXXXXXXX)" ||
	die 1 "Unable to create temporary file. FAIL"

# Unlike for BASH does not affect exit due to a signal.
trap cleanup EXIT

"$script" -d >"${tmpfile="$tmpdir/org_protocol_debug.desktop"}" ||
	die 1 "Generation of .desktop file failed. FAIL"
if "$validate" "$tmpfile"; then
	:
else
	rv="$?"
	cat "$tmpfile" 1>&2
	die "$rv" "Invalid .desktop file. FAIL"
fi
